from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];m=json.loads((R/'records/walk-exports.json').read_text(encoding='utf-8'))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>全游戏行走原画播放复核</title><style>body{margin:24px;background:#eae0c8;color:#164337;font-family:"Microsoft YaHei",sans-serif}h1{font-size:27px}select,button{font-size:18px;padding:9px;margin:4px}.pair{display:flex;gap:20px}.stage{width:384px;height:384px;position:relative;background:#fff3da;border:1px solid #b7a276}.stage.dark{background:#123b33}.stage img{width:384px;height:384px}.root{position:absolute;left:50%;top:87.5%;border:1px solid #ab6b45;width:6px;height:6px;border-radius:50%;transform:translate(-50%,-50%)}p{max-width:1000px;line-height:1.6}</style>
<h1>全游戏 · 行走原画播放复核</h1><p>仅播放本项目逐姿势独立绘制的原画。固定画布、共同身体缩放与物理根点；无插值或静图平移伪帧。漂浮角色按原身份摆动。此页仅美术验收，未接入Unity。</p><p><label>身份 <select id="actor"></select></label><button id="toggle">暂停</button><button id="prev">上一帧</button><button id="next">下一帧</button><button id="restart">从头播放</button></p><div class="pair"><div class="stage"><img id="light"><span class="root"></span></div><div class="stage dark"><img id="dark"><span class="root"></span></div></div><p id="info">载入中</p><p id="status"></p>
<script>const clips=CLIPS;let running=true,index=0,manual=0,start=performance.now(),ready=false,prev='';const caches=[],loads=[];const select=document.querySelector('#actor');for(let k=0;k<clips.length;k++){const c=clips[k],o=document.createElement('option');o.value=k;o.textContent=c.name+' · '+c.actor;select.append(o);caches.push(c.frames.map(f=>{const im=new Image;loads.push(new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(new Error(f.file));}));im.src='../'+f.file;return im;}));}function at(c,time){let t=time%c.durationMs;for(let i=0;i<c.frames.length;i++){t-=c.frames[i].durationMs;if(t<0)return i;}return c.frames.length-1;}function draw(){if(ready&&clips.length){const c=clips[index],i=running?at(c,performance.now()-start):manual%4,key=index+'_'+i;if(key!==prev){document.querySelector('#light').src=caches[index][i].src;document.querySelector('#dark').src=caches[index][i].src;for(const e of document.querySelectorAll('.root')){e.style.left=c.outputAnchorTopLeftXY[0]/1024*384+'px';e.style.top=c.outputAnchorTopLeftXY[1]/1024*384+'px';}prev=key;}document.querySelector('#info').textContent=c.name+' · 阶段 '+(i+1)+'/4 · '+c.frames[i].durationMs+'ms · 循环 '+c.durationMs+'ms';document.body.dataset.actor=c.actor;document.body.dataset.frame=i;}requestAnimationFrame(draw);}select.onchange=()=>{index=Number(select.value);manual=0;start=performance.now();prev='';};document.querySelector('#toggle').onclick=()=>{running=!running;document.querySelector('#toggle').textContent=running?'暂停':'播放';if(running)start=performance.now();};document.querySelector('#prev').onclick=()=>{running=false;manual=(manual+3)%4;document.querySelector('#toggle').textContent='播放';};document.querySelector('#next').onclick=()=>{running=false;manual=(manual+1)%4;document.querySelector('#toggle').textContent='播放';};document.querySelector('#restart').onclick=()=>{running=true;manual=0;start=performance.now();document.querySelector('#toggle').textContent='暂停';};Promise.all(loads).then(()=>{ready=true;start=performance.now();document.querySelector('#status').textContent=clips.length+' / 11组已导出供播放复核 · '+loads.length+'张实际帧已载入 · 不以此数量自动验收';document.body.dataset.ready='true';}).catch(e=>document.querySelector('#status').textContent='加载失败 '+e.message);draw();</script></html>'''
html=html.replace('<button id="toggle">','<label>速度 <select id="speed"><option value="1">正常 1×</option><option value="0.5">慢速 0.5×</option></select></label><button id="toggle">')
html=html.replace("let running=true,index=0", "let speed=1;document.querySelector('#speed').onchange=()=>{speed=Number(document.querySelector('#speed').value);start=performance.now();};let running=true,index=0")
html=html.replace('at(c,performance.now()-start)', 'at(c,(performance.now()-start)*speed)')
html=html.replace('index=Number(select.value);manual=0;', 'trace=[];transitions=0;index=Number(select.value);manual=0;')
html=html.replace("ready=false,prev='';", "ready=false,prev='',trace=[],transitions=0;")
html=html.replace("prev=key;}document.querySelector('#info')", "prev=key;trace.push(i+1);trace=trace.slice(-12);transitions++;}document.querySelector('#info')")
html=html.replace("c.durationMs+'ms';document.body", "c.durationMs+'ms · 实际切帧 '+transitions+' 次 · 最近帧序 '+trace.join('→');document.body")
html=html.replace('CLIPS',json.dumps(m['clips'],ensure_ascii=False));(R/'previews/playback.html').write_text(html,encoding='utf-8');print('Wrote walk playback review',len(m['clips']))
